<?php

declare(strict_types=1);

namespace Dodo\Installer;

use Dodo\Path;
use RuntimeException;

/** Picks, validates and prepares the directory holding DodoCD's database, uploads, releases and logs. */
final class DataDir
{
    public const SUBDIRS = ['uploads', 'releases', 'backups', 'logs', 'tmp'];

    private const DENY_HTACCESS = <<<'HTACCESS'
        # Generated by DodoCD. This folder must never be served over HTTP.
        <IfModule mod_authz_core.c>
            Require all denied
        </IfModule>
        <IfModule !mod_authz_core.c>
            Order allow,deny
            Deny from all
        </IfModule>

        HTACCESS;

    /** The outside-web-root location when it is usable, otherwise the in-tree fallback. */
    public static function propose(): string
    {
        $outside = self::outsideWebrootCandidate();
        if ($outside !== null && self::validate($outside) === null) {
            return $outside;
        }

        return self::fallback();
    }

    /** A sibling of the web root, e.g. /home/user/.dodocd-data next to /home/user/public_html. */
    public static function outsideWebrootCandidate(): ?string
    {
        $docRoot = $_SERVER['DOCUMENT_ROOT'] ?? '';
        if ($docRoot === '') {
            return null;
        }

        return Path::normalize(dirname(Path::canonical($docRoot)) . '/.dodocd-data');
    }

    public static function fallback(): string
    {
        return Path::normalize(DODO_ROOT . '/storage');
    }

    public static function isInsideWebroot(string $dir): bool
    {
        $docRoot = $_SERVER['DOCUMENT_ROOT'] ?? '';

        return $docRoot !== '' && Path::isWithin(Path::canonical($dir), Path::canonical($docRoot));
    }

    /** An error message, or null when the directory exists and is writable or can be created. */
    public static function validate(string $dir): ?string
    {
        if (!Path::isAbsolute($dir)) {
            return 'Use an absolute path.';
        }
        if (in_array('..', explode('/', str_replace('\\', '/', $dir)), true)) {
            return 'The path must not contain "..".';
        }
        if (!Path::allowedByOpenBasedir($dir)) {
            return 'PHP\'s open_basedir setting does not allow this location.';
        }
        if (is_dir($dir)) {
            return is_writable($dir) ? null : 'The directory exists but PHP cannot write to it.';
        }
        if (file_exists($dir)) {
            return 'The path exists but is not a directory.';
        }

        $parent = dirname($dir);
        while (!is_dir($parent) && dirname($parent) !== $parent && Path::allowedByOpenBasedir(dirname($parent))) {
            $parent = dirname($parent);
        }

        return is_dir($parent) && is_writable($parent) ? null : "PHP cannot create folders in {$parent}.";
    }

    /** Creates the directory and its subfolders, and blocks web access to it. Safe to run again. */
    public static function prepare(string $dir): void
    {
        $paths = array_merge([$dir], array_map(fn (string $sub) => "{$dir}/{$sub}", self::SUBDIRS));

        foreach ($paths as $path) {
            if (!is_dir($path) && !@mkdir($path, 0750, true) && !is_dir($path)) {
                throw new RuntimeException("Could not create {$path}.");
            }
        }

        // Written even outside the web root, in case the host maps it into a docroot later.
        if (file_put_contents("{$dir}/.htaccess", self::DENY_HTACCESS) === false
            || file_put_contents("{$dir}/index.html", '') === false) {
            throw new RuntimeException("Could not write the access rules in {$dir}.");
        }
    }

    /**
     * Requests a probe file in $dir over HTTP to confirm the deny rules work.
     * true = publicly readable (unsafe), false = blocked, null = could not tell
     * (loopback requests are often blocked on shared hosting).
     */
    public static function probePublicAccess(string $dir): ?bool
    {
        if (!self::isInsideWebroot($dir)) {
            return false;
        }
        if (!ini_get('allow_url_fopen')) {
            return null;
        }

        $url = self::publicUrl($dir);
        $name = 'probe-' . bin2hex(random_bytes(8)) . '.txt';
        $secret = bin2hex(random_bytes(16));

        if (@file_put_contents("{$dir}/{$name}", $secret) === false) {
            return null;
        }

        try {
            $context = stream_context_create([
                'http' => ['timeout' => 3, 'ignore_errors' => true],
                'ssl' => ['verify_peer' => false, 'verify_peer_name' => false],
            ]);
            $body = @file_get_contents("{$url}/{$name}", false, $context);

            return $body === false ? null : $body === $secret;
        } finally {
            @unlink("{$dir}/{$name}");
        }
    }

    private static function publicUrl(string $dir): string
    {
        $dir = Path::canonical($dir);

        // Prefer DodoCD's own base URL, which stays correct under aliases.
        if (Path::isWithin($dir, Path::canonical(DODO_ROOT))) {
            return dodo_origin() . rtrim(dodo_url(Path::relative($dir, Path::canonical(DODO_ROOT))), '/');
        }

        return dodo_origin() . '/' . Path::relative($dir, Path::canonical($_SERVER['DOCUMENT_ROOT']));
    }
}
